                        gctx.beginPath();
                        gctx.moveTo(tfx, tfy);     gctx.lineTo(tfx - 1, tfy - 3);
                        gctx.moveTo(tfx + 1, tfy); gctx.lineTo(tfx + 1, tfy - 4);
                        gctx.moveTo(tfx + 2, tfy); gctx.lineTo(tfx + 3, tfy - 3);
