                    gctx.fillStyle = '#5a3a2a';
                    gctx.beginPath(); gctx.arc(wbX - 8, wbY + 4, 1.5, 0, Math.PI * 2); gctx.fill();
                    // Handles
                    gctx.strokeStyle = '#7a5a3a'; gctx.lineWidth = 1.5;
                    gctx.beginPath(); gctx.moveTo(wbX + 12, wbY - 4); gctx.lineTo(wbX + 22, wbY); gctx.stroke();

