                    gctx.moveTo(wcX + 7, wcY - 6);
                    gctx.lineTo(wcX + 13, wcY - 8);
                    gctx.lineTo(wcX + 13, wcY - 5);
                    gctx.lineTo(wcX + 7, wcY - 3);
                    gctx.closePath();
                    gctx.fill();
                    // Handle
                    gctx.strokeStyle = '#0e6655'; gctx.lineWidth = 1;
                    gctx.beginPath(); gctx.arc(wcX + 3, wcY - 9, 3, Math.PI, 0); gctx.stroke();

