                    gctx.strokeStyle = '#5a5a5a'; gctx.lineWidth = 1;
                    gctx.beginPath(); gctx.moveTo(rbX - 6, rbY - 14); gctx.lineTo(rbX + 6, rbY - 14); gctx.stroke();
                    gctx.beginPath(); gctx.moveTo(rbX - 6, rbY - 4); gctx.lineTo(rbX + 6, rbY - 4); gctx.stroke();
